    c: [['should / shouldn’t', '\\b(should|shouldn[’\']t)\\b', 2], ['must / mustn’t', '\\b(must|mustn[’\']t)\\b', 2], ['needn’t / shall / could / can', '\\b(needn[’\']t|shall|could|can|may)\\b', 2]]
