    c: [['will', '\\b(will|’ll|\'ll|won’t)\\b', 1], ['going to', '\\bgoing to\\b', 1], ['Present Continuous', '\\b(am|’m|\'m|are|’re|\'re|is|’s)\\s+\\w+ing\\b', 2], ['jadval', '\\b(leaves|arrives|starts|departs|opens|closes)\\b', 1]],
    sp: { t: 'Imlo: transport so‘zlari.', i: [['schedule', 'shedule', 'sch-e-dule: sch.'], ['arrive', 'arive', 'ar-rive: ikkita r.'], ['departure', 'depature', 'de-par-ture: par.'], ['passenger', 'pasenger', 'pas-sen-ger: ikkita s.'], ['journey', 'jurney', 'jour-ney: ou.'], ['available', 'avaliable', 'a-vail-a-ble.']] },
