    col: [['pass an exam', 'imtihondan o‘tmoq', 'She *passed the exam*.'], ['fail a test', 'testdan yiqilmoq', 'He *failed the test*.'], ['meet a deadline', 'muddatga ulgurmoq', 'I *met the deadline*.'], ['take notes', 'konspekt yozmoq', 'Students *take notes* in lectures.']],
    pv: [['look up', 'qidirib topmoq (lug‘atdan)', '*Look up* the word.'], ['hand in', 'topshirmoq', '*Hand in* your essay.'], ['catch up', 'orqada qolganini yetmoq', 'I must *catch up* on homework.'], ['go over', 'qayta ko‘rib chiqmoq', 'Let’s *go over* the notes.']],
    use: [['lecture vs. lesson', 'lecture — universitetdagi ma’ruza; lesson — maktabdagi dars.', ['I attended a *lecture* on law.', 'We have an English *lesson*.']],
          ['mark vs. grade', 'mark — UK baho; grade — AQSH baho yoki sinf.', ['She got a good *mark*.', 'He is in the ninth *grade*.']]],
