    pv: [['cut down', 'kesmoq', 'They *cut down* the forest.'], ['run out of', 'tugab qolmoq', 'We *ran out of* water.'], ['throw away', 'tashlab yubormoq', 'Don’t *throw away* plastic.'], ['switch off', 'o‘chirmoq', '*Switch off* the lights.']],
    use: [['rubbish vs. waste vs. litter', 'rubbish — kundalik axlat; waste — chiqindi (umumiy); litter — ko‘chadagi tashlandiq axlat.', ['Put it in the *rubbish* bin.', 'Don’t *waste* food.']],
          ['climate vs. weather', 'weather — bugungi havo; climate — uzoq muddatli iqlim.', ['The *weather* is nice today.', 'The *climate* is dry here.']]],
