    c: [['Passive Present', '\\b(is|are|am)\\s+(\\w+ed|made|used|sold|built|written|known|called|done)\\b', 2], ['Passive Past', '\\b(was|were)\\s+(\\w+ed|made|built|written|found|sold|invented|discovered)\\b', 1], ['made of/from/by', '\\bmade (of|from|by)\\b', 1]],
