    pv: [['come up with', 'o‘ylab topmoq', 'She *came up with* an idea.'], ['set up', 'tashkil etmoq', 'They *set up* a lab.'], ['find out', 'aniqlamoq', 'We *found out* the cause.'], ['break down', 'buzilmoq', 'The machine *broke down*.']],
    use: [['invent vs. discover', 'invent — yangi narsa yaratmoq; discover — mavjud narsani topmoq.', ['Bell *invented* the phone.', 'Fleming *discovered* penicillin.']],
          ['research vs. experiment', 'research — keng tadqiqot; experiment — bitta tajriba.', ['She does *research*.', 'They did an *experiment*.']]],
