    col: [['make friends', 'do‘st orttirmoq', 'He *made friends* quickly.'], ['keep in touch', 'aloqada bo‘lmoq', 'We *keep in touch*.'], ['lose touch', 'aloqani yo‘qotmoq', 'We *lost touch*.'], ['have a row', 'janjal qilmoq', 'They *had a row*.']],
    pv: [['get on with', 'til topishmoq', 'I *get on with* her.'], ['fall out with', 'urishmoq', 'I *fell out with* him.'], ['make up', 'yarashmoq', 'We *made up*.'], ['look up to', 'hurmat qilmoq', 'I *look up to* my father.']],
    use: [['friend vs. acquaintance', 'friend — yaqin do‘st; acquaintance — tanish.', ['my best *friend*', 'a work *acquaintance*']],
          ['lend vs. borrow', 'lend — bermoq; borrow — olmoq.', ['I *lent* him a book.', 'He *borrowed* a book.']]],
