    pv: [['turn on / off', 'yoqmoq / o‘chirmoq', '*Turn off* the TV.'], ['put on / take off', 'kiymoq / yechmoq', '*Put on* your coat.'], ['pick up', 'olib ketmoq', 'I’ll *pick* you *up*.'], ['give back', 'qaytarib bermoq', '*Give* it *back*.']],
    use: [['look vs. watch vs. see', 'look — qaramoq; watch — kuzatmoq; see — ko‘rmoq.', ['*Look* at this!', 'I *watch* TV.']],
          ['take vs. bring vs. fetch', 'take — olib ketmoq; bring — olib kelmoq; fetch — borib olib kelmoq.', ['*Take* it home.', '*Bring* me a glass.']]],
    syn: [['turn down', 'reject', 'accept'], ['put off', 'postpone', 'bring forward'], ['call off', 'cancel', 'confirm'], ['end up', 'finish up', 'start out']],
    ex: [['They had to ___ the meeting because of rain. (bekor qilmoq)', 'call off'], ['She ___ her mother — they look so similar. (o‘xshaydi)', 'takes after'], ['I ran ___ an old friend yesterday. (duch keldim)', 'into'], ['Don’t ___ your work until tomorrow. (kechiktirmoq)', 'put off'], ['I usually ___ down with a book. (xotirjam bo‘lmoq)', 'wind'], ['He didn’t ___ up for the meeting. (kelmadi)', 'turn']]
