    col: [['throw a party', 'ziyofat uyushtirmoq', 'We *threw a party*.'], ['send an invitation', 'taklifnoma yubormoq', 'We *sent an invitation*.'], ['propose a toast', 'tost aytmoq', 'He *proposed a toast*.'], ['mark an occasion', 'voqeani nishonlamoq', 'We *marked the occasion*.']],
    pv: [['dress up', 'bezanmoq', 'They *dressed up*.'], ['get together', 'yig‘ilmoq', 'We *got together*.'], ['show up', 'kelmoq', 'He didn’t *show up*.'], ['set up', 'tashkil etmoq', 'They *set up* tables.']],
    use: [['wedding vs. marriage', 'wedding — marosim; marriage — nikoh holati.', ['a big *wedding*', 'a happy *marriage*']],
          ['guest vs. visitor vs. host', 'guest — taklif qilingan; visitor — tashrifchi; host — mezbon.', ['a wedding *guest*', 'a museum *visitor*']]],
    syn: [['joyous', 'happy', 'sad'], ['solemn', 'serious', 'cheerful'], ['festive', 'celebratory', 'gloomy'], ['gather', 'meet', 'scatter']],
