    sp: { t: 'Imlo: ob-havo so‘zlari.', i: [['weather', 'wether', 'weath-er: ea.'], ['temperature', 'temprature', 'tem-per-a-ture.'], ['thunderstorm', 'thunderstorn', 'thun-der-storm.'], ['hurricane', 'huricane', 'hur-ri-cane: ikkita r.'], ['earthquake', 'earthquack', 'earth-quake.'], ['disaster', 'disastar', 'dis-as-ter.']] },
