    c: [['so … that', '\\bso\\s+\\w+(\\s+\\w+)?\\s+that\\b', 1], ['such a … that', '\\bsuch\\s+(a|an)?\\s*\\w+(\\s+\\w+)?\\s+that\\b', 1], ['too … to', '\\btoo\\s+\\w+\\s+(for \\w+ )?to\\b', 1], ['enough to', '\\benough\\s+(for \\w+ )?to\\b', 1]],
