    pv: [['switch on', 'yoqmoq', '*Switch on* the lights.'], ['set up', 'o‘rnatmoq', '*Set up* the lab.'], ['carry out', 'o‘tkazmoq', '*Carry out* tests.'], ['break down', 'buzilmoq', 'It *broke down*.']],
    use: [['invention vs. discovery', 'invention — yangi narsa yaratish (telefon); discovery — mavjud narsani topish (penitsillin, Amerika).', ['an *invention*', 'a *discovery*']],
          ['device vs. devise', 'device (-ice) — ot, qurilma; devise (-ise) — fe’l, o‘ylab topmoq.', ['a small *device*', 'to *devise* a plan']]],
    syn: [['breakthrough', 'major advance', 'setback'], ['cutting-edge', 'innovative', 'outdated'], ['rely on', 'depend on', 'doubt'], ['improve', 'enhance', 'worsen']],
