    sp: { t: 'Imlo: qonun so‘zlari.', i: [['criminal', 'crimminal', 'crim-i-nal.'], ['judge', 'juge', 'judge: dg.'], ['evidence', 'evidance', 'ev-i-dence.'], ['punishment', 'punishement', 'pun-ish-ment.'], ['witness', 'witnes', 'wit-ness: ss.'], ['arrest', 'arrset', 'ar-rest: rr.']] },
