    sp: { t: 'Imlo: ta’lim so‘zlari.', i: [['education', 'eduction', 'ed-u-ca-tion.'], ['knowledge', 'knowlege', 'knowl-edge.'], ['university', 'univercity', 'u-ni-ver-si-ty.'], ['assignment', 'asignment', 'as-sign-ment: ss.'], ['semester', 'semestr', 'se-mes-ter.'], ['scholarship', 'scolarship', 'schol-ar-ship.']] },
