    pv: [['die out', 'qirilmoq', 'Species *die out*.'], ['clear up', 'ochilmoq', 'It *cleared up*.'], ['cut down', 'kesmoq', '*Cut down* trees.'], ['wipe out', 'yo‘q qilmoq', 'It *wiped out* the crops.']],
    use: [['weather vs. climate', 'weather — bugungi/qisqa muddatli holat; climate — uzoq muddatli o‘rtacha holat.', ['the *weather* today', 'a dry *climate*']],
          ['heavy vs. strong', 'heavy rain / snow / traffic; strong wind / coffee / smell — kollokatsiya.', ['*heavy* rain', '*strong* wind']]],
