    sp: { t: 'Imlo: moda so‘zlari.', i: [['fashionable', 'fashionible', 'fash-ion-a-ble.'], ['accessory', 'acessory', 'ac-ces-so-ry: cc, ss.'], ['wardrobe', 'wardrob', 'ward-robe.'], ['fabric', 'fabrik', 'fab-ric.'], ['designer', 'desiner', 'de-sign-er.'], ['elegant', 'elegent', 'el-e-gant.']] },
