  't-delete': async t => {
    if (!confirmBox('O‘quvchi va uning barcha natijalari o‘chiriladi. Ishonchingiz komilmi?', t)) return;
    await API.call('DELETE', '/t/students/' + t.dataset.id); toast('O‘chirildi.'); go('teacher');
  }
